SELECT json_build_object('kind','connection','observed_at',clock_timestamp(),'replica',pg_is_in_recovery(),'transaction_read_only',current_setting('transaction_read_only'),'replay_at',pg_last_xact_replay_timestamp(),'replication_lag_seconds',extract(epoch from now()-pg_last_xact_replay_timestamp()));
SELECT json_build_object('kind','table_estimates','table',relname,'estimated_rows',n_live_tup) FROM pg_stat_user_tables WHERE relname IN ('providers','provider_reputation','provider_sessions','inference_routes','request_profiles','fleet_snapshots');
SELECT json_build_object('kind','columns','table',table_name,'columns',array_agg(column_name ORDER BY ordinal_position)) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('providers','provider_reputation','provider_sessions','inference_routes','request_profiles','fleet_snapshots') GROUP BY table_name;
